// Transcribed from solid-js@2.0.0-rc.3, the prerelease this repository audits.
//
// `ComputeFunction`, `EffectFunction`, `EffectBundle`, `EffectOptions`,
// `Accessor`, `SourceAccessor` and `Refreshable` are byte-faithful to
// `@solidjs/signals` (`dist/types/signals.d.ts:49-50`, `:67-84`, `:88-103`,
// `dist/types/core/constants.d.ts:95-97`); `createEffect`'s two overloads to
// `dist/types/signals.d.ts:367` and `:378`; and the `createMemo` overload set
// to `types/client/hydration.d.ts:206-211`.
//
// `EffectFunction`'s `(() => void) | void` return is kept exactly. Typing it
// as `unknown` or `void` alone would invent a defect no real project can
// produce, which is the trap AGENTS.md's absolute rule names.
//
// The deprecated single-argument `createEffect` overload is transcribed
// because it is what makes 2.0's split mandatory: it returns `never`, so the
// 1.x form this fixture used to be written in is a type error rather than a
// silent difference. Option interfaces keep their caller-visible fields; a
// reduced option object cannot widen an argument or create a claim.
declare const $REFRESH: unique symbol;
export type Refreshable<T> = T & {
  readonly [$REFRESH]: any;
};
export type Accessor<T> = () => T;
export type SourceAccessor<T> = Refreshable<Accessor<T>>;
export type ComputeFunction<Prev, Next extends Prev = Prev> = (
  v: Prev
) => PromiseLike<Next> | AsyncIterable<Next> | Next;
export type EffectFunction<Prev, Next extends Prev = Prev> = (
  v: Next,
  p?: Prev
) => (() => void) | void;
export type EffectBundle<Prev, Next extends Prev = Prev> = {
  effect: EffectFunction<Prev, Next>;
  error: (err: unknown, cleanup: () => void) => void;
};
export interface EffectOptions {
  name?: string;
  defer?: boolean;
  schedule?: boolean;
}
export interface MemoOptions<T> {
  id?: string;
  name?: string;
  equals?: false | ((prev: T, next: T) => boolean);
}
export declare function createEffect<T>(
  compute: ComputeFunction<undefined | NoInfer<T>, T>,
  effectFn: EffectFunction<NoInfer<T>, T> | EffectBundle<NoInfer<T>, T>,
  options?: EffectOptions
): void;
/** @deprecated `createEffect(compute)` (single argument) is no longer supported. */
export declare function createEffect<T>(
  compute: ComputeFunction<undefined | NoInfer<T>, T>
): never;
export declare const createMemo: {
  <T>(
    compute: ComputeFunction<NoInfer<T>, T>,
    options: MemoOptions<T> & {
      loadingValue: T;
    }
  ): SourceAccessor<T>;
  <T>(compute: ComputeFunction<undefined | NoInfer<T>, T>, options?: MemoOptions<T>): SourceAccessor<T>;
};
